<section class="container section"><div class="page-head"><div><p class="overline">KHẢO THÍ / CHẤM THI</p><h1>Nhập điểm theo số phách</h1><p class="muted">Chỉ hiện các bài đã bàn giao, không hiển thị tên thí sinh.</p></div></div>
<form method="get" class="filter-bar" action="<?=e(url('quan-tri/diem'))?>"><label>Kỳ thi<select name="exam_id" onchange="this.form.submit()"><option value="">-- Chọn kỳ --</option><?php foreach($exams as $ex):?><option value="<?=$ex['id']?>" <?=$exam==$ex['id']?'selected':''?>><?=e($ex['code'])?></option><?php endforeach;?></select></label><button class="btn btn-light">Xem</button></form>
<div class="card spaced table-wrap"><table><thead><tr><th>Phòng</th><th>Môn</th><th>Số phách</th><th>Điểm hiện tại</th><th>Nhập điểm và căn cứ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['room_code'])?></td><td><?=e($r['subject'])?></td><td><code><?=e($r['blind_code'])?></code></td><td><strong><?=fmt($r['score'])?></strong></td><td><form class="gradeform" method="post" action="<?=e(url('quan-tri/diem/luu'))?>"><?=field('grade')?><input type="hidden" name="exam_id" value="<?=$exam?>"><input type="hidden" name="paper_id" value="<?=$r['id']?>"><input name="score" type="number" min="0" max="10" step="0.01" required placeholder="0–10" value="<?=e($r['score']??'')?>"><input name="basis" required placeholder="Căn cứ nhập điểm" value="<?=e($r['score_basis']??'Điểm kiểm thử IS4')?>"><button class="btn btn-main btn-small">Lưu điểm</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="empty">Chưa có bài nào được bàn giao. Hãy hoàn tất Quản lý phách trước.</p><?php endif;?></div></section>
